import { useFormStatus } from 'react-dom'

export function SyncButton() {
  const { pending } = useFormStatus()
  return (
    <button
      type="submit"
      disabled={pending}
      style={{
        background: pending ? '#9ca3af' : '#111',
        color: '#fff',
        border: 'none',
        borderRadius: 6,
        padding: '8px 14px',
        fontSize: 14,
        cursor: pending ? 'default' : 'pointer',
      }}
    >
      {pending ? 'Starting sync…' : 'Sync latest catalog'}
    </button>
  )
}

